  spPlaceholder: ["חג שמח {name}! היום חותמת כפולה על כל קפה ☕", "عيد سعيد {name}! اليوم ختم مضاعف على كل قهوة ☕", "Happy holidays {name}! Double stamps on every coffee today ☕"],
  spVars: ["אפשר לכתוב {name} לשם הלקוח ו-{business} לשם העסק.", "يمكنك كتابة {name} لاسم الزبون و-{business} لاسم المحل.", "Use {name} for the customer's name and {business} for the business name."],
  spWhen: ["מתי לשלוח", "موعد الإرسال", "When to send"],
  spReach: ["{n} לקוחות שמרו את הכרטיס בארנק ויקבלו את ההודעה ({apple} באייפון, {google} באנדרואיד).", "{n} زبائن حفظوا البطاقة في المحفظة وستصلهم الرسالة ({apple} آيفون، {google} أندرويد).", "{n} customers saved the card to a wallet and will get it ({apple} iPhone, {google} Android)."],
  spLimit: ["עד 3 הודעות ביום לעסק. Google מגבילה ל־3 התראות ביום ללקוח, כולל התראות החותמות.", "حتى 3 رسائل يومياً لكل محل. تسمح Google بثلاثة إشعارات يومياً لكل زبون، بما فيها إشعارات الأختام.", "Up to 3 messages a day per business. Google allows 3 notifications a day per customer, stamp notifications included."],
  spNotReady: ["הארנקים עוד לא מחוברים במערכת, ולכן כרגע לא תישלח התראה.", "المحافظ غير متصلة بعد، لذلك لن يُرسل إشعار حالياً.", "The wallets are not connected yet, so nothing will be sent for now."],
