  err_special_text: ["כתבו הודעה (עד 160 תווים).", "اكتب رسالة (حتى 160 حرفاً).", "Write a message (up to 160 characters)."],
  err_special_time: ["בחרו זמן מעכשיו ועד 120 יום קדימה.", "اختر وقتاً من الآن وحتى 120 يوماً.", "Pick a time from now up to 120 days ahead."],
  err_special_many: ["אפשר עד 10 הודעות ממתינות בכל פעם.", "حتى 10 رسائل منتظرة في كل مرة.", "Up to 10 scheduled messages at a time."],
