  err_phone_in_use: ["לכרטיס אחר בעסק כבר יש את המספר הזה.", "بطاقة أخرى في المشروع لديها هذا الرقم.", "Another card in this business already has this number."],
  err_no_worker_login: ["קודם צריך להגדיר כניסה בקופה עם טלפון ותאריך לידה.", "يجب أولاً إعداد الدخول في الصندوق بالهاتف وتاريخ الميلاد.", "Set up the counter sign-in with a phone and date of birth first."],
  emailTitle: ["אימייל לכניסה", "البريد لتسجيل الدخول", "Sign-in email"],
  emailHint: ["האימייל שאיתו נכנסים לחשבון ומקבלים קודים. להחלפה צריך את הסיסמה הנוכחית ואישור באימייל החדש.", "البريد الذي تدخل به وتستلم عليه الرموز. للتغيير تحتاج كلمة المرور الحالية وتأكيداً من البريد الجديد.", "The email you sign in with and get codes at. Changing it needs your current password and a confirmation from the new address."],
  newEmail: ["אימייל חדש", "بريد جديد", "New email"],
