  chkNotTranslated: ["הטקסטים ב{lname} עדיין בעברית. לקוחות שבוחרים {lname} יראו עברית. כתבו את ההטבה גם ב{lname}.", "النصوص بال{lname} ما زالت بالعبرية. الزبائن الذين يختارون {lname} سيرون العبرية. اكتبوا المكافأة بال{lname} أيضاً.", "The {lname} texts are still in Hebrew. Customers who choose {lname} will see Hebrew. Write the reward in {lname} too."],
  chkMissingText: ["חסר שם כרטיס או תיאור הטבה ב{lname}.", "ينقص اسم البطاقة أو وصف المكافأة بال{lname}.", "Card name or reward is missing in {lname}."],
  chkAllLangs: ["יש טקסט בשלוש השפות.", "يوجد نص باللغات الثلاث.", "Text is filled in for all three languages."],
  chkLongForWallet: ["חלק מהטקסטים ארוכים ועלולים להיחתך בארנקים.", "بعض النصوص طويلة وقد تُقص في المحافظ.", "Some texts are long and may be cut off in the wallets."],
  chkWalletLook: ["בארנקים (Apple ו-Google) אין גרדיינט, תמונת רקע מלאה או גופן מותאם: הכרטיס שם יוצג בצבע הרקע הראשון ובגופן של הטלפון.", "في المحافظ (Apple وGoogle) لا يوجد تدرج أو صورة خلفية كاملة أو خط مخصص: تظهر البطاقة باللون الأول وبخط الهاتف.", "Wallets (Apple and Google) have no gradients, full photo backgrounds or custom fonts: the wallet card uses the first background color and the phone's font."],
  saveDraft: ["שמירת טיוטה", "حفظ مسودة", "Save draft"],
  draftSaved: ["הטיוטה נשמרה. הלקוחות עדיין רואים את הגרסה המפורסמת.", "حُفظت المسودة. ما زال الزبائن يرون النسخة المنشورة.", "Draft saved. Customers still see the published version."],
  publish: ["פרסום לכרטיסי הלקוחות", "النشر لبطاقات الزبائن", "Publish to customer cards"],
  publishedOk: ["פורסם. כל הלקוחות רואים עכשיו את העיצוב החדש.", "تم النشر. يرى كل الزبائن التصميم الجديد الآن.", "Published. All customers now see the new design."],
  publishConfirm: ["לפרסם את העיצוב לכל כרטיסי הלקוחות? החותמות וההטבות לא משתנות.", "نشر التصميم لكل بطاقات الزبائن؟ الأختام والمكافآت لا تتغير.", "Publish this design to every customer card? Stamps and rewards don't change."],
